#!/usr/bin/env node

import { Command } from 'commander';
import chalk from 'chalk';
import ora from 'ora';
import { spawn } from 'child_process';
import fs from 'fs';
import path from 'path';
import { fileURLToPath } from 'url';
import net from 'net';

const __filename = fileURLToPath(import.meta.url);
const __dirname = path.dirname(__filename);

const PID_FILE = path.join(__dirname, '..', '.puter-api.pid');
const LOG_FILE = path.join(__dirname, '..', 'puter-api.log');

const BANNER = `
${chalk.hex('#6C5CE7').bold('╔══════════════════════════════════════════════════════╗')}
${chalk.hex('#6C5CE7').bold('║')}  ${chalk.hex('#A29BFE').bold('⚡ Puter API Bridge')}                                  ${chalk.hex('#6C5CE7').bold('║')}
${chalk.hex('#6C5CE7').bold('║')}  ${chalk.dim('Free, Unlimited OpenAI-Compatible API')}               ${chalk.hex('#6C5CE7').bold('║')}
${chalk.hex('#6C5CE7').bold('║')}  ${chalk.dim('Powered by Puter.js SDK')}                             ${chalk.hex('#6C5CE7').bold('║')}
${chalk.hex('#6C5CE7').bold('╚══════════════════════════════════════════════════════╝')}
`;

function isPortInUse(port) {
  return new Promise((resolve) => {
    const server = net.createServer();
    server.once('error', () => resolve(true));
    server.once('listening', () => {
      server.close();
      resolve(false);
    });
    server.listen(port, '127.0.0.1');
  });
}

function readPid() {
  try {
    if (fs.existsSync(PID_FILE)) {
      const data = JSON.parse(fs.readFileSync(PID_FILE, 'utf8'));
      return data;
    }
  } catch {
    // ignore
  }
  return null;
}

function isProcessRunning(pid) {
  try {
    process.kill(pid, 0);
    return true;
  } catch {
    return false;
  }
}

const program = new Command();

program
  .name('puter-api')
  .description('Turn Puter.js SDK into a free, unlimited OpenAI-compatible API')
  .version('1.0.0');

program
  .command('start')
  .description('Start the API server in the background')
  .option('-p, --port <port>', 'Port to listen on', '8741')
  .option('-H, --host <host>', 'Host to bind to', '127.0.0.1')
  .option('--foreground', 'Run in the foreground (do not daemonize)')
  .option('--api-key <key>', 'Require this API key for all requests (optional)')
  .option('--default-model <model>', 'Default model when none specified', 'gpt-4o')
  .action(async (opts) => {
    console.log(BANNER);

    const port = parseInt(opts.port, 10);
    const host = opts.host;

    // Check if already running
    const existing = readPid();
    if (existing && isProcessRunning(existing.pid)) {
      console.log(chalk.yellow('  ⚠  Server is already running'));
      console.log(chalk.dim(`     PID: ${existing.pid} | Port: ${existing.port}`));
      console.log(chalk.dim(`     Use ${chalk.white('puter-api stop')} to stop it first.`));
      process.exit(1);
    }

    // Check port availability
    if (await isPortInUse(port)) {
      console.log(chalk.red(`  ✗  Port ${port} is already in use.`));
      console.log(chalk.dim(`     Try a different port: ${chalk.white(`puter-api start --port ${port + 1}`)}`));
      process.exit(1);
    }

    if (opts.foreground) {
      // Run in foreground - import and start directly
      process.env.PUTER_API_PORT = String(port);
      process.env.PUTER_API_HOST = host;
      if (opts.apiKey) process.env.PUTER_API_KEY = opts.apiKey;
      process.env.PUTER_API_DEFAULT_MODEL = opts.defaultModel;
      const { startServer } = await import('./server.js');
      await startServer();
    } else {
      // Daemonize
      const spinner = ora({
        text: chalk.dim('Starting server...'),
        spinner: 'dots12',
        color: 'magenta',
      }).start();

      const logStream = fs.openSync(LOG_FILE, 'a');

      const env = {
        ...process.env,
        PUTER_API_PORT: String(port),
        PUTER_API_HOST: host,
        PUTER_API_DEFAULT_MODEL: opts.defaultModel,
      };
      if (opts.apiKey) env.PUTER_API_KEY = opts.apiKey;

      const child = spawn(process.execPath, [path.join(__dirname, 'server.js')], {
        detached: true,
        stdio: ['ignore', logStream, logStream],
        env,
      });

      // Write PID file
      fs.writeFileSync(PID_FILE, JSON.stringify({
        pid: child.pid,
        port,
        host,
        startedAt: new Date().toISOString(),
      }));

      child.unref();

      // Wait a bit to ensure the server started
      await new Promise((r) => setTimeout(r, 2500));

      // Verify it's running
      if (isProcessRunning(child.pid)) {
        spinner.succeed(chalk.green('Server started successfully!'));
        console.log();
        console.log(chalk.hex('#DFE6E9')('') + chalk.hex('#74B9FF').bold('  API Endpoint') + chalk.hex('#DFE6E9')(''));
        console.log(chalk.hex('#DFE6E9')('') + `  ${chalk.white.bold(`http://${host}:${port}/v1`)}` + ' '.repeat(Math.max(0, 34 - `http://${host}:${port}/v1`.length)) + chalk.hex('#DFE6E9')(''));
        console.log(chalk.hex('#DFE6E9')('') + chalk.hex('#DFE6E9')(''));
        console.log(chalk.hex('#DFE6E9')('') + chalk.hex('#74B9FF').bold('  OpenAI SDK Usage') + chalk.hex('#DFE6E9')(''));
        console.log(chalk.hex('#DFE6E9')('') + chalk.dim(`  base_url = "http://${host}:${port}/v1"`) + ' '.repeat(Math.max(0, 30 - `http://${host}:${port}/v1`.length)) + chalk.hex('#DFE6E9')(''));
        const displayKey = opts.apiKey || 'unused';
        console.log(chalk.hex('#DFE6E9')('') + chalk.dim(`  api_key  = "${displayKey}"`) + ' '.repeat(Math.max(0, 36 - displayKey.length)) + chalk.hex('#DFE6E9')(''));
        console.log(chalk.hex('#DFE6E9')('') + chalk.hex('#DFE6E9')(''));
        console.log(chalk.hex('#DFE6E9')('') + chalk.hex('#74B9FF').bold('  Server Info') + chalk.hex('#DFE6E9')(''));
        console.log(chalk.hex('#DFE6E9')('') + chalk.dim(`  PID: ${child.pid} | Log: puter-api.log`) + ' '.repeat(Math.max(0, 35 - `PID: ${child.pid} | Log: puter-api.log`.length)) + chalk.hex('#DFE6E9')(''));
        console.log();
        console.log(chalk.dim(`  Stop with: ${chalk.white('puter-api stop')}`));
        console.log(chalk.dim(`  View logs: ${chalk.white('puter-api logs')}`));
        console.log();
      } else {
        spinner.fail(chalk.red('Failed to start server.'));
        console.log(chalk.dim(`  Check logs: ${chalk.white(`cat ${LOG_FILE}`)}`));
        process.exit(1);
      }
    }
  });

program
  .command('stop')
  .description('Stop the running API server')
  .action(() => {
    console.log(BANNER);

    const data = readPid();
    if (!data) {
      console.log(chalk.yellow('  ⚠  No server is currently running.'));
      process.exit(0);
    }

    if (!isProcessRunning(data.pid)) {
      console.log(chalk.yellow('  ⚠  Server process is not running (stale PID file).'));
      try { fs.unlinkSync(PID_FILE); } catch {}
      process.exit(0);
    }

    const spinner = ora({
      text: chalk.dim('Stopping server...'),
      spinner: 'dots12',
      color: 'magenta',
    }).start();

    try {
      process.kill(data.pid, 'SIGTERM');
      // Wait for process to exit
      let attempts = 0;
      const check = setInterval(() => {
        attempts++;
        if (!isProcessRunning(data.pid) || attempts > 20) {
          clearInterval(check);
          if (attempts > 20 && isProcessRunning(data.pid)) {
            // Force kill
            try { process.kill(data.pid, 'SIGKILL'); } catch {}
          }
          try { fs.unlinkSync(PID_FILE); } catch {}
          spinner.succeed(chalk.green('Server stopped.'));
          console.log(chalk.dim(`  PID ${data.pid} terminated.`));
          console.log();
        }
      }, 250);
    } catch (err) {
      spinner.fail(chalk.red(`Failed to stop server: ${err.message}`));
      process.exit(1);
    }
  });

program
  .command('status')
  .description('Check if the API server is running')
  .action(() => {
    console.log(BANNER);

    const data = readPid();
    if (!data) {
      console.log(chalk.hex('#636E72')('  ○  Server is not running.'));
      console.log(chalk.dim(`     Start with: ${chalk.white('puter-api start')}`));
      console.log();
      process.exit(0);
    }

    if (!isProcessRunning(data.pid)) {
      console.log(chalk.yellow('  ○  Server is not running (stale PID file).'));
      try { fs.unlinkSync(PID_FILE); } catch {}
      console.log(chalk.dim(`     Start with: ${chalk.white('puter-api start')}`));
      console.log();
      process.exit(0);
    }

    console.log(chalk.green('  ●  Server is running'));
    console.log(chalk.dim(`     PID:     ${chalk.white(data.pid)}`));
    console.log(chalk.dim(`     Host:    ${chalk.white(data.host)}`));
    console.log(chalk.dim(`     Port:    ${chalk.white(data.port)}`));
    console.log(chalk.dim(`     Started: ${chalk.white(data.startedAt)}`));
    console.log(chalk.dim(`     URL:     ${chalk.white(`http://${data.host}:${data.port}/v1`)}`));
    console.log();
  });

program
  .command('logs')
  .description('View server logs')
  .option('-n, --lines <count>', 'Number of lines to show', '50')
  .option('-f, --follow', 'Follow log output')
  .action(async (opts) => {
    if (!fs.existsSync(LOG_FILE)) {
      console.log(chalk.yellow('  No log file found.'));
      process.exit(0);
    }

    if (opts.follow) {
      // Tail the file
      const { spawn: spawnProcess } = await import('child_process');
      const isWindows = process.platform === 'win32';
      let child;
      if (isWindows) {
        child = spawnProcess('powershell', ['-Command', `Get-Content '${LOG_FILE}' -Wait -Tail ${opts.lines}`], { stdio: 'inherit' });
      } else {
        child = spawnProcess('tail', ['-f', '-n', opts.lines, LOG_FILE], { stdio: 'inherit' });
      }
      child.on('exit', () => process.exit(0));
    } else {
      const content = fs.readFileSync(LOG_FILE, 'utf8');
      const lines = content.split('\n');
      const lastN = lines.slice(-parseInt(opts.lines, 10));
      console.log(lastN.join('\n'));
    }
  });

program.parse();
